mapper.insert:
insert into team ( team_id, name, logo, stadium, location, head_coach, league , club_color, founded, website ) values
( #{teamDto.teamId}, #{teamDto.name}, #{teamDto.logo}, #{teamDto.stadium}, #{teamDto.location}, #{teamDto.headCoach}, #{teamDto.league}, #{teamDto.clubColor}, #{teamDto.founded}, #{teamDto.website} )
on DUPLICATE key update team_id = VALUES(team_id), name = VALUES(name), logo = VALUES(logo), stadium = VALUES(stadium), location = VALUES(location), head_coach = VALUES(head_coach), league = VALUES(league), club_color = VALUES(club_color), founded = VALUES(founded), website = VALUES(website);

insert into Player ( player_id, team_id, name, nation, birthday, position ) values
( #{playerDto.playerId}, #{playerDto.teamDto.teamId}, #{playerDto.name}, #{playerDto.nation}, #{playerDto.birthDay}, #{playerDto.position} )
on DUPLICATE key update player_id = VALUES(player_id), team_id = VALUES(team_id), name = VALUES(name), nation = VALUES(nation), birthday = VALUES(birthday), position = VALUES(position);

insert into Standings ( standing_id, team_id, position, played_games, won, draw, lost, points, goals_for, goals_against, goal_difference, season, league ) values
( #{standingsDto.standingsId}, #{standingsDto.teamDto.teamId}, #{standingsDto.position}, #{standingsDto.playedGames}, #{standingsDto.won}, #{standingsDto.draw}, #{standingsDto.lost}, #{standingsDto.points}, #{standingsDto.goalsFor}, #{standingsDto.goalsAgainst}, #{standingsDto.goalDifference}, #{standingsDto.season}, #{standingsDto.league} )
on DUPLICATE key update standing_id = VALUES(standing_id), team_id = VALUES(team_id), position = VALUES(position), played_games = VALUES(played_games), won = VALUES(won), draw = VALUES(draw), lost = VALUES(lost), points = VALUES(points), goals_for = VALUES(goals_for), goals_against = VALUES(goals_against), goal_difference = VALUES(goal_difference), season = VALUES(season), league = VALUES(league);
